add('robot-sorting','سورت رباتیک پسته باز و بسته با دو دوربین','فناوری و هوشمندسازی',2023,'prototype','سامانه نوارنقاله/ربات','indexed-abstract','Non-destructive robotic sorting of cracked pistachio using deep learning','https://www.sciencedirect.com/science/article/abs/pii/S0925521422003970',4,'پژوهش نمونه سامانه دو دوربین و دست‌کاری رباتیک را برای جداسازی پسته باز/بسته معرفی می‌کند. این مسئله با تشخیص بیماری در باغ متفاوت است.','مقایسه هزینه، ظرفیت، آسیب مغز و آزمون پایلوت سورت؛ اپ فعلاً ربات یا سورت‌لاین را کنترل نمی‌کند.','دقت پژوهشِ یک نمونه سامانه به دوربین گوشی، کل ارقام یا توان صنعتی اثبات‌شده تعمیم داده نشده است.')
add('wild-ripeness','بینایی ماشین برای رسیدگی پسته وحشی؛ محدود به همان داده','فناوری و هوشمندسازی',2022,'controlled','پسته وحشی؛ نمونه کنترل‌شده','indexed-abstract','Development of an Intelligent Imaging System for Ripeness Determination of Wild Pistachios','https://pmc.ncbi.nlm.nih.gov/articles/PMC9572321/',2,'پژوهش ویژگی‌های رنگ/بافت و طبقه‌بندی رسیدگی را در نمونه‌های پسته وحشی آزموده است؛ مدل خود مقاله میوه‌خاص معرفی می‌شود.','طراحی پروتکل داده‌برداری رسیدگی برای رقم‌های تجاری ایران با نور، دوربین و برچسب کارشناس.','نتیجه کوچک و کنترل‌شده برای بنه/پسته وحشی، مدل آماده رسیدگی Pistacia vera یا تشخیص آفت نیست.')
add('hsi-aflatoxin','آفلاتوکسین با حسگر طیفی؛ نه عکس معمولی گوشی','ایمنی و کیفیت محصول',2025,'prototype','۳۰۰ تصویر فوق‌طیفی؛ آزمون محدود','full-section','Measuring the Level of Aflatoxin Infection in Pistachio Nuts by Applying Machine Learning Techniques to Hyperspectral Images','https://pmc.ncbi.nlm.nih.gov/articles/PMC11902545/',3,'پژوهش مدل‌های یادگیری ماشین را روی داده فوق‌طیفی و رده‌های آلودگی بررسی می‌کند. مطالعه امکان‌سنجی است، نه آزمون ایمنی عمومی پسته با دوربین گوشی.','ثبت آزمایش معتبر محموله و تفکیک «غربالگری حسگر» از «تأیید آزمایشگاه» در کیفیت محصول.','نمونه محدود، تفکیک دسته‌های آلودگی و احتمال اثر پوسته/آماده‌سازی نمونه؛ اعتبارسنجی بیرونی و صنعتی لازم است. نتیجه آن، دقت پستینو نیست.','10.3390/s25051548','Williams و همکاران')
add('food-ai-readiness','استاندارد آمادگی AI غذایی؛ فراتر از درصد دقت','ایمنی و کیفیت محصول',2026,'review','مواد غذایی مختلف؛ شامل شواهد پسته','full-section','A Preliminary Food–AI Readiness Framework for AI-Enabled Hyperspectral Systems in Fungal and Mycotoxin Risk Management','https://www.mdpi.com/2304-8158/15/16/2860',6,'مرور انتقادی، اهمیت اعتبار تحلیلی، خطای منفی، انتقال بین ابزار/فصل، توضیح‌پذیری، پایلوت عملیاتی و تأیید آزمایشگاهی را برجسته می‌کند.','الزام ثبت منبع/محدودیت، عدم نمایش درصد دقت ساختگی، آزمون روی باغ مستقل و امکان ارجاع به متخصص.','چارچوب مقدماتی و غیرمقرراتی است؛ هیچ گواهی رسمی، PRISMA کامل یا تأیید محصول از آن ادعا نشده است.','10.3390/foods15162860','Yeşil','۱۷ اوت ۲۰۲۶')
add('nonthermal-aflatoxin','روش‌های غیرحرارتی و زیست‌حسگرهای آفلاتوکسین','ایمنی و کیفیت محصول',2025,'review','پس از برداشت / فناوری آزمایشگاهی و صنعتی','indexed-summary','Processing and Real-Time Monitoring Strategies of Aflatoxin Reduction in Pistachios','https://www.mdpi.com/2304-8158/14/19/3411',1,'مرور، روش‌های غیرحرارتی، زیست‌حسگرها و پیش‌بینی خطر را کنار مدیریت مزرعه تا انبار بررسی می‌کند. کاهش خطر با تضمین حذف سم یکسان نیست.','دفتر محموله و زنجیره فرآوری، ارجاع آزمون معتبر و ارزیابی فناوری با استاندارد مرکز.','روش آزمایشگاهی یا گزارش کاهش آلودگی مجوز فرآوری خانگی و تضمین انطباق صادراتی نیست؛ دوز/فرمول شیمیایی منتقل نشده است.','10.3390/foods14193411','Gharibzahedi و Savas')
add('sustainability-2026','پایداری، هزینه آب و ریسک بلندمدت باغ','اقتصاد و پایداری',2026,'observational','کالیفرنیا و Castilla-La Mancha','indexed-summary','Comparative sustainability assessment of pistachio production: A case study of California (USA) and Castilla-La Mancha (Spain)','https://www.sciencedirect.com/science/article/pii/S2665972726002916',10,'مقایسه سامانه‌های تولید بر شاخص‌های محیطی، اقتصادی و اجتماعی و ریسک آب، شوری و اقلیم تمرکز دارد؛ سود یا آب مصرفی واحد، تمام پایداری نیست.','ثبت هزینه/عملکرد واقعی، آب مصرف‌شده و کیفیت در واحد هکتار و کیلو محصول برای تصمیم باغ.','بازه‌های داده و ساختار هزینه منطقه‌ای متفاوت‌اند؛ قیمت روز، سود تضمینی یا پیش‌بینی مالی ایران از این رکورد استخراج نمی‌شود.')

